#!/usr/bin/env python3
import sys, os, time, json, shlex, subprocess, datetime, difflib, select, termios, tty, signal
from dataclasses import dataclass, field

VERSION = "hwatch 0.3.19"
GRAY = "\x1b[38;5;240m"
RESET = "\x1b[0m"
HEADER_SUFFIX = "=" * 25
HEADER_PREFIX = "=" * 5

DESCRIPTION = "A modern alternative to the watch command, records the differences in execution results and can check this differences at after."

@dataclass
class Options:
    batch: bool = False
    beep: bool = False
    border: bool = False
    with_scrollbar: bool = False
    mouse: bool = False
    color: bool = False
    reverse: bool = False
    compress: bool = False
    no_title: bool = False
    enable_summary_char: bool = False
    line_number: bool = False
    no_help_banner: bool = False
    no_summary: bool = False
    exec_direct: bool = False
    diff_output_only: bool = False
    precise: bool = False
    after_command: str | None = None
    logfile: str | None = None
    shell: str = "sh -c"
    interval: float = 2.0
    limit: int = 5000
    tab_size: int = 4
    differences: str = "none"
    output: str = "output"
    keymaps: list = field(default_factory=list)
    command: list = field(default_factory=list)
    help: bool = False
    version: bool = False

class ParseError(Exception):
    def __init__(self, message, usage=False):
        self.message = message
        self.usage = usage

BOOL_LONG = {
    "--batch": ("batch", "--batch"),
    "--beep": ("beep", "--beep"),
    "--border": ("border", "--border"),
    "--with-scrollbar": ("with_scrollbar", "--with-scrollbar"),
    "--mouse": ("mouse", "--mouse"),
    "--color": ("color", "--color"),
    "--reverse": ("reverse", "--reverse"),
    "--compress": ("compress", "--compress"),
    "--no-title": ("no_title", "--no-title"),
    "--enable-summary-char": ("enable_summary_char", "--enable-summary-char"),
    "--line-number": ("line_number", "--line-number"),
    "--no-help-banner": ("no_help_banner", "--no-help-banner"),
    "--no-summary": ("no_summary", "--no-summary"),
    "--exec": ("exec_direct", "--exec"),
    "--diff-output-only": ("diff_output_only", "--diff-output-only"),
    "--precise": ("precise", "--precise"),
    "--help": ("help", "--help"),
    "--version": ("version", "--version"),
}
SHORT_BOOL = {
    "b": ("batch", "--batch"),
    "B": ("beep", "--beep"),
    "c": ("color", "--color"),
    "r": ("reverse", "--reverse"),
    "C": ("compress", "--compress"),
    "t": ("no_title", "--no-title"),
    "N": ("line_number", "--line-number"),
    "x": ("exec_direct", "--exec"),
    "O": ("diff_output_only", "--diff-output-only"),
    "h": ("help", "--help"),
    "V": ("version", "--version"),
}
VALUE_LONG = {
    "--aftercommand": ("after_command", "--aftercommand <after_command>", "str"),
    "--shell": ("shell", "--shell <shell_command>", "str"),
    "--interval": ("interval", "--interval <interval>", "float"),
    "--limit": ("limit", "--limit <limit>", "int"),
    "--tab-size": ("tab_size", "--tab-size <tab_size>", "int"),
    "--keymap": ("keymaps", "--keymap <keymap>", "keymap"),
}
SHORT_VALUE = {
    "A": ("after_command", "--aftercommand <after_command>", "str"),
    "s": ("shell", "--shell <shell_command>", "str"),
    "n": ("interval", "--interval <interval>", "float"),
    "L": ("limit", "--limit <limit>", "int"),
    "K": ("keymaps", "--keymap <keymap>", "keymap"),
}
OPTIONAL_LONG = {
    "--logfile": ("logfile", "--logfile [<logfile>]", "log"),
    "--differences": ("differences", "--differences [<differences>]", "diff"),
    "--output": ("output", "--output [<output>]", "output"),
}
SHORT_OPTIONAL = {
    "l": ("logfile", "--logfile [<logfile>]", "log"),
    "d": ("differences", "--differences [<differences>]", "diff"),
    "o": ("output", "--output [<output>]", "output"),
}
DIFF_VALUES = {"none", "watch", "line", "word"}
OUTPUT_VALUES = {"output", "stdout", "stderr"}


def print_help(prog):
