def err(s):
    sys.stderr.write(s)
    if not s.endswith("\n"):
        sys.stderr.write("\n")


def parse_bool(opts, attr, canon, seen_bool):
    if attr in seen_bool:
        raise ParseError(f"error: the argument '{canon}' cannot be used multiple times", usage=True)
    seen_bool.add(attr)
    setattr(opts, attr, True)


def parse_value(kind, val, optname):
    if kind == "str" or kind == "log":
        return val
    if kind == "float":
        try:
            f = float(val)
        except Exception:
            raise ParseError(f"error: invalid value '{val}' for '{optname}': invalid float literal")
        if f < 0.001:
            f = 0.001
        return f
    if kind == "int":
        try:
            if val.startswith('-'):
                raise ValueError
            return int(val, 10)
        except Exception:
            raise ParseError(f"error: invalid value '{val}' for '{optname}': invalid digit found in string")
    if kind == "diff":
        if val not in DIFF_VALUES:
            raise ParseError(f"error: invalid value '{val}' for '--differences [<differences>]'
  [possible values: none, watch, line, word]")
        return val
    if kind == "output":
        if val not in OUTPUT_VALUES:
            raise ParseError(f"error: invalid value '{val}' for '--output [<output>]'
  [possible values: output, stdout, stderr]")
        return val
    if kind == "keymap":
        return val
    return val


def set_once(opts, attr, val, seen_value):
    # Observed behavior keeps the first occurrence for value-like options.
    if attr == "keymaps":
        opts.keymaps.append(val)
    elif attr not in seen_value:
        setattr(opts, attr, val)
        seen_value.add(attr)


def parse_args(argv):
    opts = Options()
    seen_bool = set()
    seen_value = set()
    args = []
    env = os.environ.get("HWATCH")
    if env:
        try:
            args.extend(shlex.split(env))
        except ValueError:
            args.extend(env.split())
    args.extend(argv)

    i = 0
    command_started = False
    while i < len(args):
        tok = args[i]
        if command_started:
            opts.command.append(tok); i += 1; continue
        if tok == "--":
            opts.command.extend(args[i+1:]); break
        # Long option with equals
        if tok.startswith("--") and "=" in tok:
            name, val = tok.split("=", 1)
            if name in VALUE_LONG:
                attr, optname, kind = VALUE_LONG[name]
                set_once(opts, attr, parse_value(kind, val, optname), seen_value)
                i += 1; continue
            if name in OPTIONAL_LONG:
                attr, optname, kind = OPTIONAL_LONG[name]
                if kind == "diff":
                    val = parse_value(kind, val if val else "watch", optname)
                elif kind == "output":
                    val = parse_value(kind, val if val else "output", optname)
                elif kind == "log":
                    val = val or None
                set_once(opts, attr, val, seen_value)
                i += 1; continue
            # Unknown long with equals is a command.
            opts.command.extend(args[i:]); break
        if tok in BOOL_LONG:
            attr, canon = BOOL_LONG[tok]
            parse_bool(opts, attr, canon, seen_bool)
            i += 1; continue
        if tok in VALUE_LONG:
            attr, optname, kind = VALUE_LONG[tok]
            if i + 1 >= len(args):
                raise ParseError(f"error: a value is required for '{optname}' but none was supplied")
            val = args[i+1]
            set_once(opts, attr, parse_value(kind, val, optname), seen_value)
            i += 2; continue
        if tok in OPTIONAL_LONG:
            attr, optname, kind = OPTIONAL_LONG[tok]
            val = None
            if i + 1 < len(args) and args[i+1] != "--":
                # clap consumes the following non-option as the optional value; options terminate it.
                if not args[i+1].startswith('-'):
                    val = args[i+1]; i += 1
            if kind == "diff":
                val = parse_value(kind, val if val is not None else "watch", optname)
            elif kind == "output":
                val = parse_value(kind, val if val is not None else "output", optname)
            elif kind == "log":
                # no default file observed when value omitted
                val = val
            set_once(opts, attr, val, seen_value)
            i += 1; continue
        if tok.startswith('-') and tok != '-':
            # Short clusters. Forms like -dwatch use the remainder as value; -d=watch is not special.
            cluster = tok[1:]
            j = 0
            consumed_as_command = False
            while j < len(cluster):
                ch = cluster[j]
                if ch in SHORT_BOOL:
                    attr, canon = SHORT_BOOL[ch]
                    parse_bool(opts, attr, canon, seen_bool)
                    j += 1
                    continue
                if ch in SHORT_VALUE:
                    attr, optname, kind = SHORT_VALUE[ch]
                    rem = cluster[j+1:]
                    if rem:
                        val = rem
                        j = len(cluster)
                    else:
                        if i + 1 >= len(args):
                            raise ParseError(f"error: a value is required for '{optname}' but none was supplied")
                        val = args[i+1]; i += 1; j = len(cluster)
                    set_once(opts, attr, parse_value(kind, val, optname), seen_value)
                    continue
                if ch in SHORT_OPTIONAL:
                    attr, optname, kind = SHORT_OPTIONAL[ch]
                    rem = cluster[j+1:]
                    if rem:
                        # A leading '=' after a short option is not parsed by the original; the token becomes command-like.
                        if rem.startswith('='):
                            opts.command.extend(args[i:]); consumed_as_command = True; break
                        val = rem
                    else:
                        val = None
                        if i + 1 < len(args) and args[i+1] != "--" and not args[i+1].startswith('-'):
                            val = args[i+1]; i += 1
                    if kind == "diff":
                        val = parse_value(kind, val if val is not None else "watch", optname)
                    elif kind == "output":
                        val = parse_value(kind, val if val is not None else "output", optname)
                    elif kind == "log":
                        val = val
                    set_once(opts, attr, val, seen_value)
                    j = len(cluster)
                    continue
                # Unknown short option starts the command.
                opts.command.extend(args[i:]); consumed_as_command = True; break
            if consumed_as_command:
                break
            i += 1; continue
        # first positional starts the trailing command
        opts.command.extend(args[i:]); break
    return opts


def timestamp_now():
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]


def command_string(opts):
    return " ".join(opts.command)


def split_words(s):
    try:
        return shlex.split(s)
    except ValueError:
        return s.split()


def run_watched_command(opts):
    cmd_s = command_string(opts)
    ts = timestamp_now()
    try:
        if opts.exec_direct:
            argv = split_words(cmd_s)
        else:
            shell_parts = split_words(opts.shell)
            if not shell_parts:
                shell_parts = ["sh", "-c"]
            if any("{COMMAND}" in p for p in shell_parts):
                argv = [p.replace("{COMMAND}", cmd_s) for p in shell_parts]
            else:
                argv = shell_parts + [cmd_s]
        if not argv:
            stdout = stderr = ""; code = 127
        else:
            p = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout = p.stdout.decode('utf-8', 'replace')
            stderr = p.stderr.decode('utf-8', 'replace')
            code = p.returncode
    except FileNotFoundError:
        stdout = ""; stderr = "No such file or directory (os error 2)\n"; code = 127
    except Exception as e:
        stdout = ""; stderr = str(e) + "\n"; code = 1
    return {
        "timestamp": ts,
        "command": cmd_s,
        "status": code == 0,
        "output": stderr + stdout,
        "stdout": stdout,
        "stderr": stderr,
    }


def dummy_result():
    return {"timestamp":"", "command":"", "status":True, "output":"", "stdout":"", "stderr":""}


def results_differ(a, b):
    for k in ("command", "status", "output", "stdout", "stderr"):
        if a.get(k) != b.get(k):
            return True
    return False


def selected_text(result, mode):
    return result.get(mode if mode in ("stdout", "stderr") else "output", "")


def display_changed(prev, cur, mode):
    if prev.get("command") != cur.get("command") or prev.get("status") != cur.get("status"):
        return True
    return selected_text(prev, mode) != selected_text(cur, mode)


def json_line(obj):
    return json.dumps(obj, ensure_ascii=False, separators=(',', ':'))


def append_json(path, obj):
    if not path:
        return
    try:
        with open(path, 'a', encoding='utf-8') as f:
            f.write(json_line(obj) + "\n")
            f.flush()
    except Exception:
        pass


def load_last_log(path):
    last = None
    if not path or not os.path.exists(path):
        return None
    try:
        with open(path, encoding='utf-8') as f:
            for line in f:
                line=line.strip()
                if not line: continue
                try:
                    obj=json.loads(line)
                    if isinstance(obj, dict):
                        last=obj
                except Exception:
                    continue
    except Exception:
        return None
    return last


def run_after(after_command, before, after):
    if not after_command:
        return
    env = os.environ.copy()
    env["HWATCH_DATA"] = json_line({"before_result": before, "after_result": after})
    try:
        subprocess.run(after_command, shell=True, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def apply_reverse_and_numbers(text, opts):
    lines = text.split('\n')
    if opts.reverse:
        # Preserve trailing newlines the way split('\\n') exposes a final empty row.
        n = len(lines)
        pairs = list(reversed(list(enumerate(lines, start=1))))
    else:
        pairs = list(enumerate(lines, start=1))
    if opts.line_number:
        out=[]
        for idx, line in pairs:
            out.append(f"{GRAY}{idx}{RESET}{GRAY} | {RESET}{line}")
        return "\n".join(out)
    else:
        return "\n".join(line for _, line in pairs)


def diff_watch(prev, cur):
    out=[]
    for i,ch in enumerate(cur):
        if ch == '\n':
            out.append(ch); continue
        old = prev[i] if i < len(prev) else None
        if old != ch:
            out.append("\x1b[7m" + ch + "\x1b[7m")
        else:
            out.append(ch)
    out.append(RESET)
    return "".join(out)


def color_line(prefix, color, line):
    return f"\x1b[{color}m{prefix}\x1b[0m\x1b[{color}m{line}\x1b[0m"


def diff_line(prev, cur, word=False, only=False):
    a = prev.splitlines()
    b = cur.splitlines()
    sm = difflib.SequenceMatcher(None, a, b)
    outs=[]
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag == 'equal':
            if not only:
                outs.extend(b[j1:j2])
        elif tag == 'delete':
            for line in a[i1:i2]: outs.append(color_line('-  ', '31', line))
        elif tag == 'insert':
            for line in b[j1:j2]: outs.append(color_line('+  ', '32', line))
        elif tag == 'replace':
            maxn=max(i2-i1, j2-j1)
            for k in range(maxn):
                old = a[i1+k] if i1+k < i2 else None
                new = b[j1+k] if j1+k < j2 else None
                if old is not None:
                    outs.append(color_line('-  ', '31', inline_word(old, new or '', False) if word else old))
                if new is not None:
                    outs.append(color_line('+  ', '32', inline_word(new, old or '', True) if word else new))
    return "\n".join(outs)


def inline_word(line, other, added):
    # Highlight changed tokens for word mode with background colors similar to the original.
    bg = '42;37' if added else '41;37'
    toks = line.split(' ')
    otoks = other.split(' ')
    out=[]
    for i,t in enumerate(toks):
        if i: out.append(' ')
        if i >= len(otoks) or otoks[i] != t:
            out.append(f"\x1b[{bg}m{t}\x1b[0m\x1b[{'32' if added else '31'}m")
        else:
            out.append(t)
    return ''.join(out)


def render_text(prev, cur, opts):
    prev_txt = selected_text(prev, opts.output)
    cur_txt = selected_text(cur, opts.output)
    if opts.differences == "watch":
        text = diff_watch(prev_txt, cur_txt)
    elif opts.differences == "line":
        text = diff_line(prev_txt, cur_txt, word=False, only=opts.diff_output_only)
    elif opts.differences == "word":
        text = diff_line(prev_txt, cur_txt, word=True, only=opts.diff_output_only)
    else:
        text = apply_reverse_and_numbers(cur_txt, opts)
    if opts.differences != "none":
        # Reverse/line numbers in diff modes are TUI features; batch diff output is already decorated.
        return text
    return text


def print_batch_result(prev, cur, opts):
    sys.stdout.write(f"{GRAY}{HEADER_PREFIX}[{cur['timestamp']}]{HEADER_SUFFIX}{RESET}\n")
    sys.stdout.write(render_text(prev, cur, opts))
    sys.stdout.write("\n")
    if opts.beep:
        sys.stdout.write("\a\n")
    sys.stdout.flush()


def batch_loop(opts):
    prev = dummy_result()
    if opts.logfile:
        append_json(opts.logfile, dummy_result())
    while True:
        start = time.time()
        cur = run_watched_command(opts)
        full_changed = results_differ(prev, cur)
        shown_changed = display_changed(prev, cur, opts.output)
        if shown_changed:
            print_batch_result(prev, cur, opts)
        if full_changed:
            run_after(opts.after_command, prev, cur)
            if opts.logfile and prev.get('timestamp'):
                append_json(opts.logfile, prev)
            prev = cur
        if opts.precise:
            delay = opts.interval - (time.time() - start)
            if delay < 0: delay = 0
        else:
            delay = opts.interval
        time.sleep(delay)


def simple_tui(opts):
    # In the original program, invoking the TUI without a terminal quietly exits.
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        return 0
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    try:
        tty.setcbreak(fd)
        prev = dummy_result()
        next_run = 0
        cur = prev
        while True:
            now = time.time()
            if now >= next_run:
                cur = run_watched_command(opts)
                next_run = now + opts.interval
                sys.stdout.write("\x1b[2J\x1b[H")
                if not opts.no_title:
                    sys.stdout.write(f"Every {opts.interval:g}s: {command_string(opts)}\n")
                    if not opts.no_help_banner:
                        sys.stdout.write("Display help with h key\n")
                sys.stdout.write(selected_text(cur, opts.output))
                sys.stdout.flush()
                prev = cur
            r,_,_ = select.select([sys.stdin], [], [], 0.05)
            if r:
                ch = sys.stdin.read(1)
                if ch == 'q' or ch == '\x03':
                    break
                if ch == 'h':
                    sys.stdout.write("\x1b[2J\x1b[Hh: help  q: quit\n")
                    sys.stdout.flush()
        return 0
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)


def maybe_validate_keymaps(opts):
    if opts.keymaps:
        # The real tool validates action names. For malformed/unknown keymaps it prints this concise error.
        valid_actions = {"quit","help","color","line_number","reverse","diff","output","title","mouse","none"}
        for km in opts.keymaps:
            if '=' not in km or km.split('=',1)[1] not in valid_actions:
                err("Failed to parse keymap.")
                return 1
    return 0


def main(argv):
    prog = os.path.basename(sys.argv[0]) or "hwatch"
    try:
        opts = parse_args(argv)
    except ParseError as e:
        err(e.message)
        if e.usage:
            err(f"\nUsage: {prog} [OPTIONS] [command]...\n")
        err("For more information, try '--help'.")
        return 2
    if opts.help:
        print_help(prog)
        return 0
    if opts.version:
        print(VERSION)
        return 0
    km_rc = maybe_validate_keymaps(opts)
    if km_rc:
        return km_rc
    # If a logfile already exists and no command was supplied, use its latest command.
    if opts.logfile:
        last = load_last_log(opts.logfile)
        if not opts.command and last and last.get('command'):
            opts.command = [last.get('command')]
    if not opts.command:
        err("error: command not specified and logfile is empty.\n")
        err("Usage: hwatch [OPTIONS] [command]...\n")
        err("For more information, try '--help'.")
        return 2
    try:
        if opts.batch:
            batch_loop(opts)
        else:
            return simple_tui(opts)
    except KeyboardInterrupt:
        # The original is not chatty on interruption.
        try:
            while True:
                time.sleep(1)
        except Exception:
            return 0
    return 0

if __name__ == '__main__':
