def parse_bool(opts, attr, canon, seen_bool):
    if attr in seen_bool:
        raise ParseError(f"error: the argument '{canon}' cannot be used multiple times", usage=True)
    seen_bool.add(attr)
    setattr(opts, attr, True)


def parse_value(kind, val, optname):
    if kind == "str" or kind == "log":
        return val
    if kind == "float":
        try:
            f = float(val)
        except Exception:
            raise ParseError(f"error: invalid value '{val}' for '{optname}': invalid float literal")
        if f < 0.001:
            f = 0.001
        return f
    if kind == "int":
        try:
            if val.startswith('-'):
                raise ValueError
            return int(val, 10)
        except Exception:
            raise ParseError(f"error: invalid value '{val}' for '{optname}': invalid digit found in string")
    if kind == "diff":
        if val not in DIFF_VALUES:
            raise ParseError(f"error: invalid value '{val}' for '--differences [<differences>]'
