        return val
    if kind == "output":
        if val not in OUTPUT_VALUES:
            raise ParseError(f"error: invalid value '{val}' for '--output [<output>]'
  [possible values: output, stdout, stderr]")
        return val
    if kind == "keymap":
        return val
    return val


def set_once(opts, attr, val, seen_value):
    # Observed behavior keeps the first occurrence for value-like options.
    if attr == "keymaps":
        opts.keymaps.append(val)
    elif attr not in seen_value:
        setattr(opts, attr, val)
        seen_value.add(attr)


def parse_args(argv):
    opts = Options()
    seen_bool = set()
    seen_value = set()
    args = []
    env = os.environ.get("HWATCH")
    if env:
        try:
            args.extend(shlex.split(env))
        except ValueError:
            args.extend(env.split())
    args.extend(argv)

    i = 0
    command_started = False
    while i < len(args):
        tok = args[i]
        if command_started:
            opts.command.append(tok); i += 1; continue
        if tok == "--":
            opts.command.extend(args[i+1:]); break
        # Long option with equals
        if tok.startswith("--") and "=" in tok:
            name, val = tok.split("=", 1)
            if name in VALUE_LONG:
                attr, optname, kind = VALUE_LONG[name]
                set_once(opts, attr, parse_value(kind, val, optname), seen_value)
                i += 1; continue
            if name in OPTIONAL_LONG:
                attr, optname, kind = OPTIONAL_LONG[name]
                if kind == "diff":
                    val = parse_value(kind, val if val else "watch", optname)
                elif kind == "output":
                    val = parse_value(kind, val if val else "output", optname)
                elif kind == "log":
                    val = val or None
                set_once(opts, attr, val, seen_value)
                i += 1; continue
            # Unknown long with equals is a command.
            opts.command.extend(args[i:]); break
        if tok in BOOL_LONG:
            attr, canon = BOOL_LONG[tok]
            parse_bool(opts, attr, canon, seen_bool)
            i += 1; continue
        if tok in VALUE_LONG:
            attr, optname, kind = VALUE_LONG[tok]
            if i + 1 >= len(args):
                raise ParseError(f"error: a value is required for '{optname}' but none was supplied")
            val = args[i+1]
            set_once(opts, attr, parse_value(kind, val, optname), seen_value)
            i += 2; continue
        if tok in OPTIONAL_LONG:
            attr, optname, kind = OPTIONAL_LONG[tok]
            val = None
            if i + 1 < len(args) and args[i+1] != "--":
                # clap consumes the following non-option as the optional value; options terminate it.
                if not args[i+1].startswith('-'):
                    val = args[i+1]; i += 1
            if kind == "diff":
                val = parse_value(kind, val if val is not None else "watch", optname)
            elif kind == "output":
                val = parse_value(kind, val if val is not None else "output", optname)
            elif kind == "log":
                # no default file observed when value omitted
                val = val
            set_once(opts, attr, val, seen_value)
            i += 1; continue
