            # Short clusters. Forms like -dwatch use the remainder as value; -d=watch is not special.
            cluster = tok[1:]
            j = 0
            consumed_as_command = False
            while j < len(cluster):
                ch = cluster[j]
                if ch in SHORT_BOOL:
                    attr, canon = SHORT_BOOL[ch]
                    parse_bool(opts, attr, canon, seen_bool)
                    j += 1
                    continue
                if ch in SHORT_VALUE:
                    attr, optname, kind = SHORT_VALUE[ch]
                    rem = cluster[j+1:]
                    if rem:
                        val = rem
                        j = len(cluster)
                    else:
                        if i + 1 >= len(args):
                            raise ParseError(f"error: a value is required for '{optname}' but none was supplied")
                        val = args[i+1]; i += 1; j = len(cluster)
                    set_once(opts, attr, parse_value(kind, val, optname), seen_value)
                    continue
                if ch in SHORT_OPTIONAL:
                    attr, optname, kind = SHORT_OPTIONAL[ch]
                    rem = cluster[j+1:]
                    if rem:
                        # A leading '=' after a short option is not parsed by the original; the token becomes command-like.
                        if rem.startswith('='):
