        opts.command.extend(args[i:]); break
    return opts


def timestamp_now():
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]


def command_string(opts):
    return " ".join(opts.command)


def split_words(s):
    try:
        return shlex.split(s)
    except ValueError:
        return s.split()


def run_watched_command(opts):
    cmd_s = command_string(opts)
    ts = timestamp_now()
    try:
        if opts.exec_direct:
            argv = split_words(cmd_s)
        else:
            shell_parts = split_words(opts.shell)
            if not shell_parts:
                shell_parts = ["sh", "-c"]
            if any("{COMMAND}" in p for p in shell_parts):
                argv = [p.replace("{COMMAND}", cmd_s) for p in shell_parts]
            else:
                argv = shell_parts + [cmd_s]
        if not argv:
            stdout = stderr = ""; code = 127
        else:
            p = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout = p.stdout.decode('utf-8', 'replace')
            stderr = p.stderr.decode('utf-8', 'replace')
            code = p.returncode
    except FileNotFoundError:
        stdout = ""; stderr = "No such file or directory (os error 2)\n"; code = 127
    except Exception as e:
        stdout = ""; stderr = str(e) + "\n"; code = 1
    return {
        "timestamp": ts,
        "command": cmd_s,
        "status": code == 0,
        "output": stderr + stdout,
        "stdout": stdout,
        "stderr": stderr,
