def dummy_result():
    return {"timestamp":"", "command":"", "status":True, "output":"", "stdout":"", "stderr":""}


def results_differ(a, b):
    for k in ("command", "status", "output", "stdout", "stderr"):
        if a.get(k) != b.get(k):
            return True
    return False


def selected_text(result, mode):
    return result.get(mode if mode in ("stdout", "stderr") else "output", "")


def display_changed(prev, cur, mode):
    if prev.get("command") != cur.get("command") or prev.get("status") != cur.get("status"):
        return True
    return selected_text(prev, mode) != selected_text(cur, mode)


def json_line(obj):
    return json.dumps(obj, ensure_ascii=False, separators=(',', ':'))


def append_json(path, obj):
    if not path:
        return
    try:
        with open(path, 'a', encoding='utf-8') as f:
            f.write(json_line(obj) + "\n")
            f.flush()
    except Exception:
        pass


def load_last_log(path):
    last = None
    if not path or not os.path.exists(path):
        return None
    try:
        with open(path, encoding='utf-8') as f:
            for line in f:
                line=line.strip()
                if not line: continue
                try:
                    obj=json.loads(line)
                    if isinstance(obj, dict):
                        last=obj
                except Exception:
                    continue
    except Exception:
        return None
    return last


def run_after(after_command, before, after):
    if not after_command:
        return
    env = os.environ.copy()
    env["HWATCH_DATA"] = json_line({"before_result": before, "after_result": after})
    try:
        subprocess.run(after_command, shell=True, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def apply_reverse_and_numbers(text, opts):
    lines = text.split('\n')
    if opts.reverse:
        # Preserve trailing newlines the way split('\\n') exposes a final empty row.
        n = len(lines)
        pairs = list(reversed(list(enumerate(lines, start=1))))
    else:
        pairs = list(enumerate(lines, start=1))
    if opts.line_number:
        out=[]
        for idx, line in pairs:
            out.append(f"{GRAY}{idx}{RESET}{GRAY} | {RESET}{line}")
        return "\n".join(out)
    else:
        return "\n".join(line for _, line in pairs)


def diff_watch(prev, cur):
    out=[]
    for i,ch in enumerate(cur):
        if ch == '\n':
            out.append(ch); continue
        old = prev[i] if i < len(prev) else None
        if old != ch:
            out.append("\x1b[7m" + ch + "\x1b[7m")
        else:
            out.append(ch)
    out.append(RESET)
    return "".join(out)


def color_line(prefix, color, line):
    return f"\x1b[{color}m{prefix}\x1b[0m\x1b[{color}m{line}\x1b[0m"


def diff_line(prev, cur, word=False, only=False):
    a = prev.splitlines()
    b = cur.splitlines()
    sm = difflib.SequenceMatcher(None, a, b)
    outs=[]
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag == 'equal':
            if not only:
                outs.extend(b[j1:j2])
        elif tag == 'delete':
            for line in a[i1:i2]: outs.append(color_line('-  ', '31', line))
        elif tag == 'insert':
            for line in b[j1:j2]: outs.append(color_line('+  ', '32', line))
        elif tag == 'replace':
            maxn=max(i2-i1, j2-j1)
