def inline_word(line, other, added):
    # Highlight changed tokens for word mode with background colors similar to the original.
    bg = '42;37' if added else '41;37'
    toks = line.split(' ')
    otoks = other.split(' ')
    out=[]
    for i,t in enumerate(toks):
        if i: out.append(' ')
        if i >= len(otoks) or otoks[i] != t:
            out.append(f"\x1b[{bg}m{t}\x1b[0m\x1b[{'32' if added else '31'}m")
        else:
            out.append(t)
    return ''.join(out)


def render_text(prev, cur, opts):
    prev_txt = selected_text(prev, opts.output)
    cur_txt = selected_text(cur, opts.output)
    if opts.differences == "watch":
        text = diff_watch(prev_txt, cur_txt)
    elif opts.differences == "line":
        text = diff_line(prev_txt, cur_txt, word=False, only=opts.diff_output_only)
    elif opts.differences == "word":
        text = diff_line(prev_txt, cur_txt, word=True, only=opts.diff_output_only)
    else:
        text = apply_reverse_and_numbers(cur_txt, opts)
    if opts.differences != "none":
        # Reverse/line numbers in diff modes are TUI features; batch diff output is already decorated.
        return text
    return text


def print_batch_result(prev, cur, opts):
    sys.stdout.write(f"{GRAY}{HEADER_PREFIX}[{cur['timestamp']}]{HEADER_SUFFIX}{RESET}\n")
    sys.stdout.write(render_text(prev, cur, opts))
    sys.stdout.write("\n")
    if opts.beep:
        sys.stdout.write("\a\n")
