        cur = run_watched_command(opts)
        full_changed = results_differ(prev, cur)
        shown_changed = display_changed(prev, cur, opts.output)
        if shown_changed:
            print_batch_result(prev, cur, opts)
        if full_changed:
            run_after(opts.after_command, prev, cur)
